package org.tvshell.iptvnator.server;

/** The page a phone opens for "Add from phone" (self-contained: no network). */
final class PairingPage {
    private PairingPage() {
    }

    static final String HTML = "<!doctype html>\n"
        + "<html lang=\"en\"><head><meta charset=\"utf-8\">\n"
        + "<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n"
        + "<title>NaviTV - Add a source</title>\n"
        + "<style>\n"
        + ":root{color-scheme:dark;--bg:#14151b;--card:#1f2029;--text:#f3f3f6;--muted:#a3a4b2;--accent:#f5a623;--line:#3a3b48;--bad:#ff6b6b;--good:#5dd39e}\n"
        + "*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:16px/1.45 system-ui,-apple-system,Segoe UI,Roboto,sans-serif}\n"
        + "main{max-width:480px;margin:0 auto;padding:24px 16px 40px}\n"
        + ".brand{display:flex;align-items:center;gap:10px;margin-bottom:18px}.logo{width:36px;height:36px;border-radius:9px;background:var(--accent);color:var(--bg);display:grid;place-items:center;font-weight:800;font-size:20px}\n"
        + "h1{font-size:1.35rem;margin:0}p.lead{color:var(--muted);margin:0 0 18px}\n"
        + ".tabs{display:grid;grid-template-columns:1fr 1fr;gap:6px;background:var(--card);padding:4px;border-radius:12px;margin-bottom:16px}\n"
        + ".tabs button{border:0;border-radius:9px;padding:10px;font:inherit;font-weight:600;background:transparent;color:var(--muted)}\n"
        + ".tabs button[aria-selected=true]{background:var(--accent);color:var(--bg)}\n"
        + "label{display:block;font-weight:600;margin:12px 0 6px}input{width:100%;padding:12px;border-radius:10px;border:1px solid var(--line);background:var(--card);color:var(--text);font:inherit}\n"
        + "input:focus{outline:2px solid var(--accent);outline-offset:1px}.hint{color:var(--muted);font-size:.85rem;margin-top:4px}\n"
        + ".send{margin-top:20px;width:100%;border:0;border-radius:12px;padding:14px;font:inherit;font-weight:700;background:var(--accent);color:var(--bg)}\n"
        + ".send:disabled{opacity:.6}.status{margin-top:16px;padding:12px;border-radius:10px;display:none}.status.ok{display:block;background:rgba(93,211,158,.15);color:var(--good)}\n"
        + ".status.err{display:block;background:rgba(255,107,107,.15);color:var(--bad)}[hidden]{display:none!important}\n"
        + "</style></head><body><main>\n"
        + "<div class=\"brand\"><div class=\"logo\">N</div><h1>Add a source to your TV</h1></div>\n"
        + "<p class=\"lead\">Type your login here and it appears on the TV. Nothing is stored on this phone.</p>\n"
        + "<div class=\"tabs\" role=\"tablist\"><button type=\"button\" role=\"tab\" id=\"t-xtream\" aria-selected=\"true\">Xtream login</button><button type=\"button\" role=\"tab\" id=\"t-m3u\" aria-selected=\"false\">M3U link</button></div>\n"
        + "<form id=\"f\" autocomplete=\"off\">\n"
        + "<div id=\"code-row\"><label for=\"code\">Code shown on the TV</label><input id=\"code\" name=\"code\" inputmode=\"numeric\" maxlength=\"6\" pattern=\"[0-9]{6}\" placeholder=\"6 digits\"></div>\n"
        + "<label for=\"title\">Name (optional)</label><input id=\"title\" name=\"title\" maxlength=\"200\" placeholder=\"My provider\">\n"
        + "<div id=\"xtream\"><label for=\"server\">Server address</label><input id=\"server\" name=\"serverUrl\" inputmode=\"url\" autocapitalize=\"off\" spellcheck=\"false\" placeholder=\"http://example.com:8080\">\n"
        + "<div class=\"hint\">The host your provider gave you, with the port if there is one.</div>\n"
        + "<label for=\"user\">Username</label><input id=\"user\" name=\"username\" autocapitalize=\"off\" spellcheck=\"false\">\n"
        + "<label for=\"pass\">Password</label><input id=\"pass\" name=\"password\" type=\"password\" autocapitalize=\"off\" spellcheck=\"false\"></div>\n"
        + "<div id=\"m3u\" hidden><label for=\"url\">Playlist link</label><input id=\"url\" name=\"url\" inputmode=\"url\" autocapitalize=\"off\" spellcheck=\"false\" placeholder=\"http://example.com/get.php?...\"></div>\n"
        + "<button class=\"send\" id=\"send\" type=\"submit\">Send to TV</button>\n"
        + "<div class=\"status\" id=\"status\" role=\"status\"></div>\n"
        + "</form></main>\n"
        + "<script>\n"
        + "(function(){var type='xtream';var q=new URLSearchParams(location.search);var c=q.get('c');\n"
        + "if(c&&/^[0-9]{6}$/.test(c)){document.getElementById('code').value=c;document.getElementById('code-row').hidden=true;history.replaceState(null,'','/');}\n"
        + "function pick(t){type=t;document.getElementById('t-xtream').setAttribute('aria-selected',t==='xtream');document.getElementById('t-m3u').setAttribute('aria-selected',t==='m3u');document.getElementById('xtream').hidden=t!=='xtream';document.getElementById('m3u').hidden=t!=='m3u';}\n"
        + "document.getElementById('t-xtream').onclick=function(){pick('xtream')};document.getElementById('t-m3u').onclick=function(){pick('m3u')};\n"
        + "var status=document.getElementById('status');function show(ok,msg){status.className='status '+(ok?'ok':'err');status.textContent=msg;}\n"
        + "var messages={code:'That code does not match the one on the TV.',locked:'Too many wrong codes. Open Add from phone on the TV again.',missing:'Fill in the server, username and password.',url:'Enter a link that starts with http:// or https://.',done:'This TV already received a source. Open Add from phone on the TV again to add another.'};\n"
        + "document.getElementById('f').onsubmit=function(e){e.preventDefault();var f=e.target;var body=new URLSearchParams();body.set('type',type);\n"
        + "['code','title','serverUrl','username','password','url'].forEach(function(n){var el=f.elements[n];if(el)body.set(n,el.value);});\n"
        + "var btn=document.getElementById('send');btn.disabled=true;show(true,'Sending...');\n"
        + "fetch('/add',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:body.toString()}).then(function(r){return r.json()}).then(function(r){\n"
        + "if(r.ok){show(true,'Sent! Your TV is adding it now. You can close this page.');f.reset();}else{show(false,messages[r.error]||'Something went wrong. Try again.');btn.disabled=false;}\n"
        + "}).catch(function(){show(false,'Could not reach the TV. Make sure this phone is on the same Wi-Fi and the Add from phone screen is still open.');btn.disabled=false;});};\n"
        + "})();\n"
        + "</script></body></html>\n";
}
